// Independent-tool fixture producer. Run from the repository root:
// dart run test/support/emit_archive_package_writers.dart /tmp/package-output
// python3 test/support/check_archive_package_writers.py /tmp/package-output
// These files are generated by the production writers, then checked by native
// libarchive, GNU ar, and dpkg-deb rather than by CrispCloud's readers.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';
import 'package:crisp_cloud/services/archive_write_model.dart';

import 'archive_package_fixtures.dart';
import 'archive_package_writer_fixtures.dart';

Future<void> main(List<String> arguments) async {
  if (arguments.length != 1) {
    throw ArgumentError('Supply an output directory for native validation.');
  }
  final directory = await Directory(arguments.single).create(recursive: true);
  final manifest = <Map<String, Object?>>[];
  final timestamp = DateTime.fromMillisecondsSinceEpoch(
    1700000000000,
    isUtc: true,
  );
  final content = utf8.encode('CrispCloud package writer\n' * 200);

  Future<void> save(String name, Uint8List bytes) =>
      File('${directory.path}/$name').writeAsBytes(bytes).then((_) {});

  Future<void> create(
    String filename,
    String kind, {
    String? encoding,
    bool crc = false,
    bool gnu = false,
  }) async {
    final uidKey = '$kind.uid', gidKey = '$kind.gid';
    Map<String, Object?> attributes() => {
      uidKey: 123,
      gidKey: 456,
      if (kind == 'cpio') 'cpio.variant': crc ? '070702' : '070701',
      if (kind == 'ar' && gnu) 'ar.nameStyle': 'gnu',
      if (kind == 'xar' && encoding != null) 'xar.encoding': encoding,
    };
    final entries = <ArchiveWriteEntry>[
      if (kind != 'ar')
        packageEntry(
          'docs',
          [],
          directory: true,
          mode: 0x1e8,
          modified: timestamp,
          attributes: attributes(),
        ),
      packageEntry(
        kind == 'ar' ? 'hello.txt' : 'docs/hello.txt',
        content,
        mode: 0x1a0,
        modified: timestamp,
        attributes: attributes(),
      ),
      packageEntry(
        'long-日本語-file-name.txt',
        [1, 2, 3, 0, 255],
        mode: 0x1a4,
        modified: timestamp,
        attributes: attributes(),
      ),
      packageEntry(
        'empty',
        [],
        mode: 0x180,
        modified: timestamp,
        attributes: attributes(),
      ),
    ];
    await save(filename, await packageOutput(kind, entries));
    manifest.add({
      'file': filename,
      'kind': kind,
      'entries': [
        for (final entry in entries)
          {
            'path': entry.path,
            'size': entry.size,
            'mode': kind == 'ar'
                ? entry.mode
                : (entry.isDirectory ? 0x4000 : 0x8000) | entry.mode!,
            'uid': 123,
            'gid': 456,
            'mtime': 1700000000,
            'sha256': sha256.convert(await entry.read()).toString(),
          },
      ],
    });
  }

  await create('common.ar', 'ar');
  await create('gnu.ar', 'ar', gnu: true);
  await create('newc.cpio', 'cpio');
  await create('crc.cpio', 'cpio', crc: true);
  for (final encoding in {
    'stored': 'application/octet-stream',
    'zlib': 'application/x-gzip',
    'bzip2': 'application/x-bzip2',
    'xz': 'application/x-xz',
  }.entries) {
    await create('${encoding.key}.xar', 'xar', encoding: encoding.value);
  }

  Future<void> repack(String filename, String kind, Uint8List original) async {
    final sourceName = 'source-$filename';
    await save(sourceName, original);
    final fixture = await PackageRewriteFixture.open(original, kind);
    try {
      if (!fixture.inspection.supported) {
        throw StateError(fixture.inspection.reason!);
      }
      await save(filename, await fixture.repack());
      manifest.add({'file': filename, 'kind': kind, 'source': sourceName});
    } finally {
      await fixture.close();
    }
  }

  await repack('reference.ar', 'ar', referenceGnuAr());
  await repack('reference.cpio', 'cpio', referenceNewc());
  // The independently produced fixture has a deliberately unrelated trailing
  // 20-byte block; writable profiles refuse to discard opaque heap material.
  final xar = referenceXar();
  await repack('reference.xar', 'xar', xar.sublist(0, xar.length - 20));
  await repack('package.deb', 'deb', debianFixture().archive);
  await File('${directory.path}/manifest.json')
      .writeAsString(const JsonEncoder.withIndent('  ').convert(manifest));
  stdout.writeln('Wrote ${manifest.length} native validation cases.');
}
